/**
 * \file
 * \brief Check validity of cmake options
 *
 * The file fsoeoptions.h is generated by cmake from fsoeoptions.h.in.
 * If any option in fsoeoptions.h has an invalid value, this file will
 * ensure that a compiler error is generated, causing build to fail.
 */

#include <fsoeoptions.h>
#include <stdint.h>

/* The size of the application parameters is encoded in a 16 bit number.
 * See ETG.5100 ch. 8.2.2.5 "Parameter state".
 */
#if (FSOE_APPLICATION_PARAMETERS_MAX_SIZE > UINT16_MAX)
#error "Application parameters can't be larger than 65535 bytes"
#endif

/* An FSoE frame with a single process data byte is the smallest possible.
 * See ETG.5100 ch. 8.1.1 "Safety PDU structure".
 */
#if (FSOE_PROCESS_DATA_MAX_SIZE < 1)
#error "Process data can't be smaller than 1 byte"
#endif

/* An FSoE frame larger than 6 bytes contains an even number of data bytes.
 * See ETG.5100 ch. 8.1.1 "Safety PDU structure".
 */
#if ((FSOE_PROCESS_DATA_MAX_SIZE > 1) && ((FSOE_PROCESS_DATA_MAX_SIZE % 2) != 0))
#error "Size of process data must be even or 1"
#endif

/* The (non-mandatory) function CalcCrc() defined in the FSoE specification
 * encodes the size of a frame as an 8 bit number. An FSoE frame of size 255
 * bytes contains 126 process data bytes.
 * For supporting larger frames, the stack would need to modify CalcCrc().
 * See ETG.5100 ch. A.1 "Hash function calculation".
 */
#if (FSOE_PROCESS_DATA_MAX_SIZE > 126)
#error "Stack does not support process data larger than 126 bytes"
#endif
